+document.querySelectorAll('.question-btn').forEach(btn => {
+  btn.addEventListener('click', () => {
+    const example = btn.closest('.example');
+    const details = example.querySelector('.details');
+    const isOpen = example.classList.contains('open');
+
+    if (isOpen) {
+      details.style.maxHeight = details.scrollHeight + 'px';
+      requestAnimationFrame(() => {
+        requestAnimationFrame(() => {
+          details.style.maxHeight = '0';
+        });
+      });
+      example.classList.remove('open');
+      btn.setAttribute('aria-expanded', 'false');
+    } else {
+      details.style.maxHeight = details.scrollHeight + 'px';
+      example.classList.add('open');
+      btn.setAttribute('aria-expanded', 'true');
+    }
+  });
+
+  // Clean up inline style after open transition so resizing works
+  const details = btn.closest('.example').querySelector('.details');
+  details.addEventListener('transitionend', () => {
+    if (btn.getAttribute('aria-expanded') === 'true') {
+      details.style.maxHeight = 'none';
+    }
+  });
+});
+
